/* Авторская практика ЕГЭ по электромагнитным колебаниям и волнам. */
(() => {
  const format = value => String(Number(value.toFixed(5))).replace('.', ',');
  const variants = [
    ['Период колебаний заряда', 'мс', n => [
      `Заряд в идеальном контуре описывается законом q = 6·10⁻⁶ cos(2000πt/${n}) Кл, где t — время в секундах. Найди период в миллисекундах.`, n,
      'Сравни коэффициент при t с циклической частотой ω.',
      `T = 2π/ω = ${n}/1000 с = ${n} мс.`
    ]],
    ['Формула Томсона', 'мкс', n => [
      `В идеальном контуре L = ${n*n} мкГн и C = 25 нФ. Найди период в микросекундах. Прими π = 3,14.`, 2*3.14*Math.sqrt(25e-3)*n,
      'Период свободных колебаний равен 2π√(LC).',
      `LC = ${25*n*n}·10⁻¹⁵ с², поэтому T = 2·3,14·√(${25*n*n}·10⁻¹⁵) с ≈ ${format(2*3.14*Math.sqrt(25e-3)*n)} мкс.`
    ]],
    ['Настройка частоты контура', 'кГц', n => [
      `Собственная частота идеального контура равна ${4*n} кГц. Ёмкость увеличивают в четыре раза при прежней индуктивности. Найди новую частоту в килогерцах.`, 2*n,
      'Из формулы Томсона частота обратно пропорциональна квадратному корню из ёмкости.',
      `Частота уменьшается в √4 = 2 раза и становится равной ${2*n} кГц.`
    ]],
    ['Ток в колебательном контуре', 'мА', n => [
      `Амплитуда заряда конденсатора равна ${n} мкКл, циклическая частота колебаний — 4000 рад/с. Определи амплитуду силы тока в миллиамперах.`, 4*n,
      'Ток — производная заряда по времени, поэтому Iₘ = ωqₘ.',
      `Iₘ = 4000·${n}·10⁻⁶ А = ${4*n} мА.`
    ]],
    ['Энергия катушки в контуре', 'мкДж', n => [
      `В идеальном контуре амплитуда напряжения на конденсаторе ёмкостью ${2*n} мкФ равна 10 В. В некоторый момент напряжение составляет 6 В. Найди энергию магнитного поля катушки в микроджоулях.`, 64*n,
      'Полная энергия равна CUₘ²/2. Вычти текущую энергию конденсатора.',
      `W = C(Uₘ² − U²)/2 = ${2*n}·(100 − 36)/2 = ${64*n} мкДж.`
    ]],
    ['Перенос энергии в контуре', 'мкс', n => [
      `При t = 0 конденсатор идеального контура максимально заряжен, ток равен нулю. Период составляет ${4*n} мкс. Через сколько микросекунд ток впервые достигнет максимального модуля?`, n,
      'Максимум модуля тока наступает, когда конденсатор впервые полностью разряжается.',
      `От максимума заряда до первого нуля проходит четверть периода. t = ${4*n}/4 = ${n} мкс.`
    ]],
    ['Длина радиоволны', 'м', n => [
      `Передатчик излучает в вакууме волну частотой ${5*n} МГц. Найди длину волны в метрах. Прими c = 3·10⁸ м/с.`, 60/n,
      'Для волны в вакууме λ = c/ν. Переведи мегагерцы в герцы.',
      `λ = 3·10⁸/(${5*n}·10⁶) = 60/${n} м ≈ ${format(60/n)} м.`
    ]],
    ['Волна в диэлектрике', 'см', n => [
      `Электромагнитная волна частотой ${25*n} МГц входит из вакуума в однородный диэлектрик с показателем преломления 1,5. Найди длину волны в среде в сантиметрах. Прими c = 3·10⁸ м/с.`, 800/n,
      'При переходе границы частота сохраняется, а фазовая скорость в среде равна c/1,5.',
      `λ = (2·10⁸)/(${25*n}·10⁶) м = 800/${n} см ≈ ${format(800/n)} см.`
    ]],
    ['Радиолокация', 'км', n => [
      `Радар получил эхо от цели через ${20*n} мкс после отправки импульса. Определи расстояние до неподвижной цели в километрах. Скорость радиоволны 3·10⁸ м/с.`, 3*n,
      'Измеренное время включает путь до цели и обратно.',
      `Расстояние равно ct/2 = 3·10⁸·${20*n}·10⁻⁶/2 м = ${3*n} км.`
    ]],
    ['Резонансная настройка приёмника', 'м', n => [
      `Радиоприёмник настроен на ${10*n} МГц. Ёмкость контура уменьшают в четыре раза, индуктивность сохраняют. Найди длину принимаемой волны в вакууме в метрах. Прими c = 3·10⁸ м/с.`, 15/n,
      'Из формулы Томсона частота после уменьшения ёмкости возрастает в √4 = 2 раза.',
      `Новая частота ${20*n} МГц. Длина волны равна 3·10⁸/(${20*n}·10⁶) = 15/${n} м ≈ ${format(15/n)} м.`
    ]]
  ];

  for (const [index, [title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 15; variant++) {
      const [question, rawAnswer, ...steps] = build(variant + 1);
      const url = index < 6
        ? 'https://phys-ege.sdamgia.ru/test?category_id=248&filter=all'
        : 'https://phys-ege.sdamgia.ru/test?a=view_many&cat_id%5B%5D=248&cat_id%5B%5D=253&cat_id%5B%5D=255&cat_id%5B%5D=367&cat_id%5B%5D=368&filter=all';
      tasks.push({
        id: `ege-physics-waves-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Электромагнитные колебания и волны',
        examTopic: 'physics-ege-waves',
        level: [0, 2, 6].includes(index) ? 0 : [4, 7, 9].includes(index) ? 2 : 1,
        title, question, unit, steps,
        answer: Number(rawAnswer.toFixed(5)),
        hints: [steps[0]],
        solution: steps.join(' '),
        review: {plan: steps[0]},
        source: {
          name: 'Решу ЕГЭ',
          id: index < 6 ? 'Колебательный контур' : 'Колебания и волны',
          type: 'тематический каталог',
          url,
          note: 'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

